#pragma once

// Scoopy captive portal frontend.
// Human-editable source lives at firmware/captive-portal/index.html.
// Keep this embedded copy in sync when the UI changes.

namespace esphome::captive_portal {

static const char SCOOPY_INDEX[] = R"SCOOPY(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#F5F0E6"><title>Scoopy Setup</title><style>
:root{--cream:#F5F0E6;--light:#FBF8F1;--ink:#1C211B;--pink:#E496B3;--pink2:#F5D8E3;--blue:#B6D6EB;--blue2:#DFECF5;--muted:#687067;--border:rgba(28,33,27,.14)}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--cream);color:var(--ink);font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px 16px;overflow-x:hidden}.decor{position:fixed;inset:0;pointer-events:none;overflow:hidden}.blob{position:absolute;border-radius:999px;opacity:.75}.pinkblob{width:190px;height:190px;top:-70px;right:-55px;background:var(--pink2)}.blueblob{width:220px;height:220px;left:-90px;bottom:-80px;background:var(--blue2)}.shell{width:100%;max-width:430px;position:relative;z-index:1}.card{overflow:hidden;background:var(--light);border:1px solid rgba(28,33,27,.10);border-radius:28px;box-shadow:0 22px 60px rgba(28,33,27,.10)}.bar{display:grid;grid-template-columns:1fr 1fr;height:8px}.bar i:first-child{background:var(--pink)}.bar i:last-child{background:var(--blue)}.content{padding:34px 30px 28px}.brand{text-align:center;margin-bottom:24px;font-size:31px;line-height:1;font-weight:800;letter-spacing:-1px}h1{margin:0;text-align:center;font-size:25px;line-height:1.2;letter-spacing:-.5px}.intro{max-width:310px;margin:10px auto 30px;text-align:center;color:var(--muted);font-size:15px;line-height:1.55}.field{margin-bottom:18px}label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}select,input{width:100%;min-height:52px;border:1px solid var(--border);border-radius:15px;background:var(--cream);color:var(--ink);padding:0 15px;font:inherit;font-size:16px;outline:none}select:focus,input:focus{border-color:var(--pink);box-shadow:0 0 0 4px rgba(228,150,179,.18)}.manual{margin-top:9px;border:0;padding:0;background:none;color:var(--ink);font:inherit;font-size:13px;font-weight:650;text-decoration:underline;text-decoration-color:var(--pink);text-decoration-thickness:2px;text-underline-offset:3px}.manualField{display:none;margin-top:14px}.manualField.visible{display:block}.connect{width:100%;min-height:54px;margin-top:6px;border:0;border-radius:16px;background:var(--ink);color:var(--cream);font:inherit;font-size:16px;font-weight:800}.connect:disabled{opacity:.7}.status{display:none;margin-top:18px;padding:14px 16px;border:1px solid rgba(182,214,235,.8);border-radius:15px;background:var(--blue2);font-size:13px;line-height:1.5;text-align:center}.status.visible{display:block}.deviceWrap{display:flex;justify-content:center;margin-top:23px}.device{display:inline-flex;align-items:center;gap:7px;margin:0;padding:7px 12px;border-radius:999px;background:linear-gradient(90deg,var(--pink2),var(--blue2));color:var(--muted);font-size:11px}.dot{width:7px;height:7px;border-radius:50%;background:var(--pink)}.device strong{color:var(--ink)}.sprinkles{display:flex;justify-content:center;gap:8px;margin-top:19px}.sprinkles i{width:16px;height:5px;border-radius:999px}.sprinkles i:nth-child(odd){background:var(--pink);transform:rotate(15deg)}.sprinkles i:nth-child(even){background:var(--blue);transform:rotate(-12deg)}.footer{margin:17px 0 0;text-align:center;color:#7C837A;font-size:11px}@media(max-width:420px){body{align-items:flex-start;padding-top:14px}.content{padding:30px 22px 24px}.card{border-radius:23px}.brand{font-size:29px}}
</style></head><body><div class="decor"><div class="blob pinkblob"></div><div class="blob blueblob"></div></div><main class="shell"><section class="card"><div class="bar"><i></i><i></i></div><div class="content"><div class="brand">Scoopy</div><h1>Welcome to Scoopy!</h1><p class="intro">Let's get your Scoopy connected to Wi-Fi.</p><form id="f"><div class="field"><label for="net">Wi-Fi network</label><select id="net"><option value="">Loading networks…</option></select><button class="manual" id="toggle" type="button">Can't see your network?</button><div class="manualField" id="manual"><label for="ssid">Network name</label><input id="ssid" autocomplete="off" placeholder="Enter Wi-Fi name"></div></div><div class="field"><label for="psk">Password</label><input id="psk" type="password" autocomplete="current-password" placeholder="Wi-Fi password"></div><button class="connect" id="connect" type="submit">Connect Scoopy</button></form><div class="status" id="status" role="status"></div><div class="deviceWrap"><p class="device"><span class="dot"></span>Device: <strong id="name">Scoopy</strong></p></div><div class="sprinkles"><i></i><i></i><i></i><i></i></div></div></section><p class="footer">Scoopy Node · Open-source smart room control</p></main><script>
const net=document.getElementById('net'),nameEl=document.getElementById('name'),toggle=document.getElementById('toggle'),manual=document.getElementById('manual'),ssid=document.getElementById('ssid'),psk=document.getElementById('psk'),form=document.getElementById('f'),status=document.getElementById('status'),connect=document.getElementById('connect'),connectionTimeoutMs=30000,statusPollMs=1000,connectingMessage="Scoopy is connecting to Wi-Fi. This page should close automatically. If it doesn't, you can close it once the Scoopy setup network disappears. Hopefully you won't need to read any of this because the page has already vanished by now. If you're still here, either you're an impressively quick reader, your Wi-Fi is taking its sweet time, Scoopy is having a little think, or I've made a mistake somewhere. Give it another moment, and if the Scoopy setup network disappears then everything has probably worked exactly as intended.";
function show(msg){status.textContent=msg;status.classList.add('visible')}function reset(){connect.disabled=false;connect.textContent='Connect Scoopy';psk.focus();psk.select()}function sleep(ms){return new Promise(r=>setTimeout(r,ms))}async function waitForWifi(){const deadline=Date.now()+connectionTimeoutMs;let unavailable=0;while(Date.now()<deadline){await sleep(statusPollMs);try{const r=await fetch('/wifi-status',{cache:'no-store'});if(!r.ok)throw 0;const s=await r.json();if(s.connected)return'connected';unavailable=0}catch(e){unavailable++;if(unavailable>=3)return'portal-gone'}}return'timeout'}
function networks(aps){net.innerHTML='<option value="">Choose a network</option>';const m=new Map;(aps||[]).filter(a=>a&&a.ssid).sort((a,b)=>(b.rssi||-100)-(a.rssi||-100)).forEach(a=>{if(!m.has(a.ssid))m.set(a.ssid,a)});m.forEach(a=>{const o=document.createElement('option');o.value=a.ssid;o.textContent=a.ssid;net.appendChild(o)});if(!m.size)net.options[0].textContent='No networks found'}
async function load(){try{const r=await fetch('/config.json',{cache:'no-store'});if(!r.ok)throw 0;const c=await r.json();nameEl.textContent=c.name||'Scoopy';networks(c.aps)}catch(e){net.innerHTML='<option value="">Unable to scan networks</option>';show('Scoopy could not load nearby Wi-Fi networks. You can still enter your network name manually.')}}
toggle.onclick=()=>{const v=manual.classList.toggle('visible');toggle.textContent=v?'Choose from scanned networks':"Can't see your network?";if(v){net.value='';ssid.focus()}};
form.onsubmit=async e=>{e.preventDefault();const chosen=manual.classList.contains('visible')?ssid.value.trim():net.value;if(!chosen){show('Choose a Wi-Fi network or enter the network name manually.');return}connect.disabled=true;connect.textContent='Connecting…';show('Connecting Scoopy to '+chosen+'…');try{const q=new URLSearchParams({ssid:chosen,psk:psk.value}),r=await fetch('/wifisave?'+q.toString(),{cache:'no-store'});if(!r.ok)throw 0;show(connectingMessage);const outcome=await waitForWifi();if(outcome==='timeout'){reset();show('Scoopy could not connect using those Wi-Fi settings. Check the network name and password, then try again.');return}if(outcome==='connected'){show('Connected! Scoopy is leaving setup mode. Your device should return to its normal Wi-Fi automatically.');return}show('Scoopy has left setup mode. Your device should return to its normal Wi-Fi automatically.')}catch(e){reset();show('Scoopy could not save those Wi-Fi settings. Check the network name and password, then try again.')}};load();
</script></body></html>)SCOOPY";

}  // namespace esphome::captive_portal
